-- RF-09 follow-up: the secondary style gets its own text.
-- The result text of a style is written for the predominant style ("o seu estilo predominante é o X"), and
-- it was also shown for the secondary one. The new block 'secondary' holds a text written for the second
-- style. Source: docs/RF-07-diagnosis-content-and-pdf-generation/content-source.json (generated by scripts/generate-content-seed.mjs).
-- Migration 11 stays as released; this one adds the block to the check and the 6 texts to version 1.

alter table public.content_templates drop constraint content_templates_block_check;
alter table public.content_templates add constraint content_templates_block_check
  check (block in ('result', 'secondary', 'pieces', 'accessories', 'guidance'));

insert into public.content_templates (version_id, kind, style, block, position, body)
select v.id, 'style_block', t.style, 'secondary', 1, t.body
  from public.content_versions v
 cross join (values
    ('esportivo_natural', '{nome}, o seu segundo estilo é o Esportivo/Natural. Ele traz para o seu visual o conforto, a praticidade e a naturalidade: é a parte de você que gosta de se vestir de um jeito leve, sem esforço aparente, e de se sentir à vontade em qualquer lugar. Esse toque suaviza o seu estilo principal e faz a sua imagem comunicar simplicidade e autenticidade.'),
    ('tradicional', '{nome}, o seu segundo estilo é o Tradicional. Ele traz para o seu visual a discrição, a organização e o gosto pelo que é atemporal: é a parte de você que prefere peças clássicas, de qualidade, que nunca saem de moda. Esse toque dá base e equilíbrio ao seu estilo principal e faz a sua imagem comunicar seriedade e confiança.'),
    ('elegante', '{nome}, o seu segundo estilo é o Elegante. Ele traz para o seu visual o refinamento e a sofisticação: é a parte de você que gosta de qualidade, de cortes impecáveis e de um visual harmonioso e bem cuidado. Esse toque dá acabamento ao seu estilo principal e faz a sua imagem comunicar classe e bom gosto.'),
    ('romantico', '{nome}, o seu segundo estilo é o Romântico. Ele traz para o seu visual a delicadeza, a feminilidade e os detalhes suaves: é a parte de você que gosta de tecidos fluidos e de tons delicados. Esse toque suaviza o seu estilo principal e faz a sua imagem comunicar gentileza e charme.'),
    ('criativo', '{nome}, o seu segundo estilo é o Criativo. Ele traz para o seu visual a originalidade e a liberdade de se expressar: é a parte de você que gosta de misturar cores, texturas e estampas. Esse toque dá personalidade ao seu estilo principal e faz a sua imagem comunicar curiosidade e alegria.'),
    ('dramatico', '{nome}, o seu segundo estilo é o Dramático. Ele traz para o seu visual o impacto e a presença marcante: é a parte de você que gosta de contrastes e de linhas definidas. Esse toque dá força ao seu estilo principal e faz a sua imagem comunicar ousadia e determinação.')
  ) as t(style, body)
 where v.version = 1;
